#!/usr/bin/env python3
"""Write, or with --check compare, the third-party notices of a release.

Both files are generated from Cargo.lock and the crates' own files:

- THIRD_PARTY_NOTICES.md, between its markers: every crate that the
  db-sync-alt binary is built from (the normal, not build- or dev-only,
  dependencies of the `db-sync-alt` package for x86_64-unknown-linux-gnu, as
  `cargo metadata` resolves them from Cargo.lock), with its version and
  license expression.
- THIRD_PARTY_LICENSES.txt: the license, copyright and notice files that each
  of those crates ships, every distinct text once, and the license of the
  midnight-node material compiled into the binary. A crate that ships no such
  file is given the SPDX text of its declared license (.github/scripts/spdx/)
  and the authors its manifest names; the script prints these crates.

The crate files are read where `cargo metadata` unpacked them in the Cargo home.
"""
import argparse
from collections import Counter
import json
from pathlib import Path
import re
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[2]
NOTICES = ROOT/'THIRD_PARTY_NOTICES.md'
LICENSES = ROOT/'THIRD_PARTY_LICENSES.txt'
SPDX = Path(__file__).resolve().parent/'spdx'
BEGIN = '<!-- BEGIN generated by .github/scripts/third_party_notices.py -->'
END = '<!-- END generated -->'
BINARY = 'db-sync-alt'
TARGET = 'x86_64-unknown-linux-gnu'
# File names of license, copyright and notice files at the top of a crate.
LICENSE_FILE = re.compile(r'^(licen[cs]e|copying|copyright|notice|unlicense)([-_.].*)?$', re.IGNORECASE)
# Material from midnight-node that the binary holds besides crates: the
# node's SQL statements (the query catalogue) and its network values (the
# profiles). Each entry names the license file kept in this repository.
OTHER_MATERIAL = [
    ('midnight-node node-2.1.101', 'Apache-2.0',
     'the node\'s SQL statements and network configuration values, compiled into the binary',
     'docs/licenses/midnight-node-LICENSE'),
    ('Partner Chains, as vendored in midnight-node node-2.1.101', 'Apache-2.0',
     'the SQL statements of its db-sync data source, compiled into the binary',
     'docs/licenses/partner-chains-LICENSE'),
]


def crates(metadata):
    packages = {p['id']: p for p in metadata['packages']}
    nodes = {n['id']: n for n in metadata['resolve']['nodes']}
    root = next(p['id'] for p in metadata['packages'] if p['name'] == BINARY and p['source'] is None)
    seen, stack = set(), [root]
    while stack:
        current = stack.pop()
        if current in seen:
            continue
        seen.add(current)
        stack.extend(d['pkg'] for d in nodes[current]['deps']
                     if any(kind['kind'] is None for kind in d['dep_kinds']))
    external = [packages[i] for i in seen if packages[i]['source'] is not None]
    missing = sorted(p['name'] for p in external if not p['license'])
    if missing:
        raise SystemExit('crates without a license expression: '+', '.join(missing))
    return sorted(external, key=lambda p: (p['name'], p['version']))


def notices_section(external):
    lines = [BEGIN, '',
             f'{len(external)} crates, the normal dependencies of `{BINARY}` for `{TARGET}`',
             'as resolved from `Cargo.lock`. The license, copyright and notice files of',
             'each crate are in [`THIRD_PARTY_LICENSES.txt`](THIRD_PARTY_LICENSES.txt),',
             'which the release archive and the container image carry.', '',
             '| License expression | Crates |', '| --- | --- |']
    for expression, count in sorted(Counter(p['license'] for p in external).items(),
                                    key=lambda item: (-item[1], item[0])):
        lines.append(f'| `{expression}` | {count} |')
    lines += ['', '| Crate | Version | License expression |', '| --- | --- | --- |']
    lines += [f"| {p['name']} | {p['version']} | `{p['license']}` |" for p in external]
    lines += ['', END]
    return '\n'.join(lines)


def normalized(text):
    lines = [line.rstrip() for line in text.replace('\r\n', '\n').replace('\r', '\n').split('\n')]
    while lines and not lines[0]:
        lines.pop(0)
    while lines and not lines[-1]:
        lines.pop()
    return '\n'.join(lines)


def read_text(path, owner):
    try:
        return normalized(path.read_bytes().decode('utf-8'))
    except UnicodeDecodeError:
        raise SystemExit(f'{owner}: {path.name} is not UTF-8 text')


def license_files(package):
    """The crate's license, copyright and notice files, by relative path."""
    directory = Path(package['manifest_path']).parent
    if not directory.is_dir():
        raise SystemExit(f"{package['name']} {package['version']}: no unpacked source at {directory}; "
                         'run `cargo metadata` first')
    found = {}
    for path in directory.iterdir():
        if path.is_file() and LICENSE_FILE.match(path.name):
            found[path.name] = path
    reuse = directory/'LICENSES'
    if reuse.is_dir():
        for path in reuse.iterdir():
            if path.is_file():
                found['LICENSES/'+path.name] = path
    if package.get('license_file'):
        path = directory/package['license_file']
        if path.is_file():
            found.setdefault(package['license_file'], path)
    return [(name, found[name]) for name in sorted(found)]


def spdx_identifiers(expression):
    words = re.findall(r'[A-Za-z0-9.+-]+', expression)
    identifiers, skip = [], False
    for word in words:
        if skip:
            skip = False
            continue
        if word == 'WITH':
            skip = True
        elif word not in {'AND', 'OR'} and word not in identifiers:
            identifiers.append(word)
    if any(word == 'WITH' for word in words):
        raise SystemExit(f'license exception in {expression!r}: add its text to the fallback rule')
    return identifiers


def licenses_file(external):
    texts, order = {}, []

    def reference(text):
        if text not in texts:
            texts[text] = len(order)+1
            order.append(text)
        return texts[text]

    crate_lines, fallbacks = [], []
    for package in external:
        owner = f"{package['name']} {package['version']}"
        files = license_files(package)
        if files:
            parts = [f'{name} [{reference(read_text(path, owner))}]' for name, path in files]
            crate_lines.append(f"{owner} ({package['license']}): "+', '.join(parts))
            continue
        parts = []
        for identifier in spdx_identifiers(package['license']):
            path = SPDX/f'{identifier}.txt'
            if not path.is_file():
                raise SystemExit(f'{owner} ships no license file and .github/scripts/spdx/{identifier}.txt '
                                 'does not exist')
            parts.append(f'SPDX {identifier} text [{reference(read_text(path, identifier))}]')
        authors = '; '.join(package.get('authors') or []) or 'not named in its manifest'
        crate_lines.append(f"{owner} ({package['license']}): no license file in the crate; "
                           +', '.join(parts)+f'; copyright holders, as its manifest names its authors: {authors}')
        fallbacks.append(owner)
    other_lines = []
    for name, expression, what, relative in OTHER_MATERIAL:
        text = read_text(ROOT/relative, name)
        other_lines.append(f'{name} ({expression}), {what}: {Path(relative).name} [{reference(text)}]')
    lines = [
        'Third-party licenses of db-sync-alt',
        '',
        'Generated by .github/scripts/third_party_notices.py from Cargo.lock and the',
        "crates' own files. Do not edit it by hand.",
        '',
        f'The db-sync-alt binary is built from the {len(external)} crates listed below (the',
        f'normal dependencies of the {BINARY} package for {TARGET}, as',
        'resolved from Cargo.lock) and holds material from midnight-node. Each entry',
        'names the license, copyright and notice files it ships and the number of',
        'their text in the TEXTS section, where every distinct text appears once. A',
        'crate that ships none of these files is given the SPDX text of its declared',
        'license and the authors its manifest names.',
        '',
        'CRATES',
        '',
        *crate_lines,
        '',
        'OTHER MATERIAL',
        '',
        *other_lines,
        '',
        'TEXTS',
    ]
    for number, text in enumerate(order, start=1):
        lines += ['', f'==== [{number}] ====', '', text]
    return '\n'.join(lines)+'\n', fallbacks


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('--check', action='store_true', help='fail if a file is not current')
    parser.add_argument('--metadata', type=Path, help='read `cargo metadata` output from this file')
    args = parser.parse_args()
    if args.metadata:
        metadata = json.loads(args.metadata.read_text())
    else:
        metadata = json.loads(subprocess.check_output(
            ['cargo', 'metadata', '--format-version', '1', '--locked', '--filter-platform', TARGET],
            cwd=ROOT))
    external = crates(metadata)
    text = NOTICES.read_text()
    start, end = text.find(BEGIN), text.find(END)
    if start < 0 or end < start:
        raise SystemExit('THIRD_PARTY_NOTICES.md lacks the generated-section markers')
    notices = text[:start]+notices_section(external)+text[end+len(END):]
    licenses, fallbacks = licenses_file(external)
    if fallbacks:
        print('Crates without a license file, given the SPDX text of their license: '+', '.join(fallbacks))
    stale = [path.name for path, content in ((NOTICES, notices), (LICENSES, licenses))
             if not path.is_file() or path.read_text() != content]
    if args.check:
        if stale:
            print(' and '.join(stale)+' not current; run python3 .github/scripts/third_party_notices.py')
            return 1
        print(f'THIRD_PARTY_NOTICES.md and THIRD_PARTY_LICENSES.txt cover the current {len(external)} crates.')
        return 0
    NOTICES.write_text(notices)
    LICENSES.write_text(licenses)
    print(f'THIRD_PARTY_NOTICES.md and THIRD_PARTY_LICENSES.txt written for {len(external)} crates '
          f'({len(licenses.encode())} bytes of license texts).')
    return 0


if __name__ == '__main__':
    sys.exit(main())
